if (ObjC.available) {
    var targetClass = "YTIPlayerResponse";
    var targetMethod = "- isMonetized";

    if (ObjC.classes[targetClass] === undefined) {
        console.log("Class " + targetClass + " not found!");
    } else {
        if (ObjC.classes[targetClass][targetMethod] === undefined) {
            console.log("Method " + targetMethod + " not found in " + targetClass);
        } else {
            var hook = ObjC.classes[targetClass][targetMethod];
            console.log("Hooking " + targetClass + " " + targetMethod);

            Interceptor.attach(hook.implementation, {
                onEnter: function(args) {
                    console.log("[*] " + targetClass + " " + targetMethod + " called");
                },
                onLeave: function(retval) {
                    console.log("[*] " + targetClass + " " + targetMethod + " originally returned: " + retval);
                    retval.replace(0);
                    console.log("[*] Modified return value to: " + retval);
                }
            });
        }
    }
} else {
    console.log("Objective-C runtime is not available!");
}

function interceptActionWithTarget(actionSelector, target) {
    console.log("\tSet hook on: " + target.$className + "." + actionSelector.readUtf8String() + "()")
    var impl = target.methodForSelector_(actionSelector)
    Interceptor.attach(impl, {
        onEnter: function(a) {
            this.log = Array()
            this.log.push("(" + a[0] + ") " + target.$className + "." + actionSelector.readUtf8String() + "()")
        },
        onLeave: function(r) {
            console.log(this.log.join('\n') + '\n')
        }})
}

function interceptActionWithoutTarget(actionSelector, uiControl) {
    var uiApp = ObjC.classes.UIApplication.sharedApplication()
    // frida bug? anyway we can't call this 
    // var actionTarget = uiApp._targetInChainForAction_sender_(actionSelector, uiControl)
    // but we can 
    var targetInChainForActionPrototype = new NativeFunction(ObjC.api.objc_msgSend, "pointer", ["pointer","pointer","pointer", "pointer"])
    var actionTargetPtr = targetInChainForActionPrototype(uiApp, ObjC.selector("_targetInChainForAction:sender:"), actionSelector, uiControl)
    if (actionTargetPtr != "0x0") {
        var actionTarget = new ObjC.Object(actionTargetPtr) 
        interceptActionWithTarget(actionSelector, actionTarget)
    } else {
        console.warn("\tCan't get target for selector: " + actionSelector.readUtf8String())
    }
}

function interceptUIAction(uiAction) {
    // At least in swift 5.5 next scheme work
    // block invoke points to swift helper that calls blockAdr+0x20
    var blockAddr = uiAction.$ivars._handler.handle
    var closurePtr = blockAddr.add(0x20).readPointer()
    var closureName = DebugSymbol.fromAddress(closurePtr).name 
    console.log("\tSet hook on: " + closureName)
    Interceptor.attach(closurePtr, {
        onEnter: function(a) {
            this.log = Array()
            this.log.push("Called " + closureName)
        },
        onLeave: function(r) {
            console.log(this.log.join('\n') + '\n')
        }})
}

function setInteceptionOnRegistredCallbacks(uiControl) {
    console.log("Get callbacks of " + uiControl.$className + " " + uiControl.handle)
    var targetActions = uiControl.$ivars._targetActions
    if (targetActions == null) {
        console.log("\tNo callbacks found")
        return
    }

    var count = targetActions.count().valueOf()

    for (let i = 0; i !== count; i++) {
        var action = targetActions.objectAtIndex_(i)
        // First case when UIAction specified
        if (action.$ivars._actionHandler != null) {
            var uiAction = action.$ivars._actionHandler
            interceptUIAction(uiAction)
        } else if (action.$ivars._action != null && 
                    action.$ivars._action != "0x0" &&
                    action.$ivars._target != null) {
            var actionSelector = action.$ivars._action
            var actionTarget = action.$ivars._target
            interceptActionWithTarget(actionSelector, actionTarget)
        }
        else if (action.$ivars._action != null && 
            action.$ivars._action != "0x0"){
            var actionSelector = action.$ivars._action
            interceptActionWithoutTarget(actionSelector, uiControl)
        }
        else {
            console.error("Invalid UIControlTargetAction with actionHandler and action seted to null")
            continue
        }
    }
}

function hookAllUIControlsAction() {
    console.log("Getting all UIControl's")
    var uiControls = ObjC.chooseSync(ObjC.classes.UIControl)
    uiControls.forEach(control => {setInteceptionOnRegistredCallbacks(control)})
}

function get_timestamp()
{
	var today = new Date();
	var timestamp = today.getFullYear() + '-' + (today.getMonth()+1) + '-' + today.getDate() + ' ' + today.getHours() + ":" + today.getMinutes() + ":" + today.getSeconds() + ":" + today.getMilliseconds();
	return timestamp;
}

function hook_class_method(class_name, method_name)
{
	var hook = eval('ObjC.classes.'+class_name+'["'+method_name+'"]');
		Interceptor.attach(hook.implementation, {
			onEnter: function(args) {
			console.log("[*] [" + get_timestamp() + " ] Detected call to: " + class_name + " -> " + method_name);
		}
	});
}

function run_hook_all_methods_of_classes_app_only()
{
	console.log("[*] Started: Hook all methods of all app only classes");
	var free = new NativeFunction(Module.findExportByName(null, 'free'), 'void', ['pointer'])
    var copyClassNamesForImage = new NativeFunction(Module.findExportByName(null, 'objc_copyClassNamesForImage'), 'pointer', ['pointer', 'pointer'])
    var p = Memory.alloc(Process.pointerSize)
    Memory.writeUInt(p, 0)
    var path = ObjC.classes.NSBundle.mainBundle().executablePath().UTF8String()
    var pPath = Memory.allocUtf8String(path)
    var pClasses = copyClassNamesForImage(pPath, p)
    var count = Memory.readUInt(p)
    var classesArray = new Array(count)
    for (var i = 0; i < count; i++)
    {
        var pClassName = Memory.readPointer(pClasses.add(i * Process.pointerSize))
        classesArray[i] = Memory.readUtf8String(pClassName)
		var className = classesArray[i]
		if (ObjC.classes.hasOwnProperty(className))
		{
			//console.log("[+] Class: " + className);
			//var methods = ObjC.classes[className].$methods;
			var methods = ObjC.classes[className].$ownMethods;
			for (var j = 0; j < methods.length; j++)
			{
				try
				{
					var className2 = className;
					var funcName2 = methods[j];
					//console.log("[-] Method: " + methods[j]);
					hook_class_method(className2, funcName2);
					//console.log("[*] [" + get_timestamp() + "] Hooking successful: " + className2 + " -> " + funcName2);
				}
				catch(err)
				{
					console.log("[*] [" + get_timestamp() + "] Hooking Error: " + err.message);
				}
			}
		}
    }
    free(pClasses)
	console.log("[*] Completed: Hook all methods of all app only classes");
}

function hook_all_methods_of_classes_app_only()
{
	setImmediate(run_hook_all_methods_of_classes_app_only)
}

hook_all_methods_of_classes_app_only()

if (ObjC.available) {
    var UIApplication = ObjC.classes.UIApplication;

    function tryAttach(methodName, label) {
        var m = UIApplication[methodName];
        if (!m) {
            console.log('[*] ' + methodName + ' not found on UIApplication');
            return;
        }
        Interceptor.attach(m.implementation, {
            onEnter: function(args) {
                try {
                    // args[0] = self, args[1] = _cmd, args[2] = NSURL *
                    if (args[2].isNull()) {
                        console.log(label + ' called with NULL url');
                        return;
                    }
                    var url = new ObjC.Object(args[2]);
                    // absoluteString is the most reliable readable form
                    var s = (typeof url.absoluteString === 'function') ? url.absoluteString().toString() : url.toString();
                    console.log(label + ' -> ' + s);
                } catch (e) {
                    console.log(label + ' -> error reading url: ' + e);
                }
            }
        });
        console.log('[*] Attached to UIApplication ' + methodName);
    }

    tryAttach('- openURL:', '[openURL:]');
    tryAttach('- openURL:options:completionHandler:', '[openURL:options:completionHandler:]');

} else {
    console.log('Objective-C runtime is not available!');
}

